<script setup lang="ts">import{ref}from'vue';import{api}from'../../services/api';import PageHeader from'../../components/PageHeader.vue';const kinds=[['DYNAMIC','动态'],['CIRCLE_DYNAMIC','圈子动态'],['MATERIAL','素材']]as const;const kind=ref('DYNAMIC');const title=ref('');const body=ref('');const tags=ref('');const error=ref('');const status=ref('');const busy=ref(false);async function submit(){if(!title.value.trim()||!body.value.trim()){error.value='请填写标题和正文';return;}error.value='';busy.value=true;try{const created=await api.post('/content',{kind:kind.value,title:title.value,body:body.value,tags:tags.value.split(/[,，]/).map(v=>v.trim()).filter(Boolean)});await api.post(`/content/${created.data.id}/submit`);status.value='已提交审核';}catch(e:any){error.value=e?.response?.data?.message??'发布失败';}finally{busy.value=false;}}</script><template><main class="page business-page"><PageHeader title="发布内容" subtitle="分享你的直播生活"/><div class="segmented"><button v-for="item in kinds" :key="item[0]" :class="{active:kind===item[0]}" @click="kind=item[0]">{{item[1]}}</button></div><section class="form-panel"><label>标题<input v-model="title" aria-label="内容标题" maxlength="60" placeholder="给内容起个标题"></label><label>正文<textarea v-model="body" aria-label="内容正文" rows="8" placeholder="说点什么吧…"></textarea></label><label>标签<input v-model="tags" aria-label="内容标签" placeholder="直播，日常，幕后"></label><p v-if="error" class="form-error">{{error}}</p><p v-if="status" class="success-note">✓ {{status}}</p><button class="primary-button wide" :disabled="busy" @click="submit">{{busy?'提交中…':'提交审核'}}</button></section><aside class="tip-card">内容将先进入审核队列，通过后对外展示；驳回原因会在主播中心显示。</aside></main></template>
